message.content:
{
  "lesson_summary": "Today's lesson plans to teach students how to compare and order unlike fractions. It will cover two methods: cross multiplication, using the example of Hira's bottle with $\\frac{2}{3}$ and her friend's bottle with $\\frac{3}{5}$, and finding common denominators. The lesson also plans to address common misconceptions about associating the cross-products with the correct fraction.",
  "questions": [
    {
      "index": 1,
      "slo_id": "S1",
      "level": "understand",
      "question": "Hira had $\\frac{2}{3}$ of a bottle and her friend had $\\frac{3}{5}$ of a bottle. When comparing them using cross multiplication, what is the product of the numerator of the second fraction and the denominator of the first fraction?",
      "options": [
        "$3 \\times 3$",
        "$2 \\times 5$",
        "$2 \\times 3$"
      ],
      "correct_index": 0,
      "explanation": "To compare $\\frac{2}{3}$ and $\\frac{3}{5}$ using cross multiplication, you multiply the numerator of the first fraction by the denominator of the second fraction ($2 \\times 5 = 10$), and the numerator of the second fraction by the denominator of the first fraction ($3 \\times 3 = 9$). The question asks for the second product.",
      "selected_because": "The lesson's own example of comparing Hira's bottle with her friend's bottle.",
      "distractor_misconceptions": {
        "1": "multiplies numerator of first by denominator of second",
        "2": "multiplies numerator by its own denominator"
      },
      "option_feedback": {
        "correct": "That's right! When comparing $\\frac{2}{3}$ and $\\frac{3}{5}$, the product of the numerator of the second fraction ($3$) and the denominator of the first fraction ($3$) is $3 \\times 3 = 9$.",
        "wrong": {
          "1": "This is the product of the numerator of the first fraction and the denominator of the second fraction. Remember, for cross multiplication, you multiply the numerator of one fraction by the denominator of the other. The question asked for the product involving the second fraction's numerator.",
          "2": "This is multiplying the numerator by its own denominator. In cross multiplication, you multiply the numerator of one fraction by the denominator of the *other* fraction. For $\\frac{2}{3}$ and $\\frac{3}{5}$, the products are $2 \\times 5$ and $3 \\times 3$."
        }
      }
    }
  ]
}
